mapper.select:
		SELECT
			NVL(NVL(te.INSTRUCTION_ID, teh.INSTRUCTION_ID), NVL(tie.INSTRUCTION_ID, tieh.INSTRUCTION_ID)) ORDER_ID,
			case when ptl.PROFIT_TYPE = '01' then 'FVTPL' else 'AC' end as invAim,

			LEFT JOIN T_ENTRUSTHISTORY teh ON std.APPLY_TRADE_ID = teh.REPORT_NO and teh.ENTRUST_STATUS IN ('2', '5', '8')
			LEFT JOIN T_ENTRUST te ON std.APPLY_TRADE_ID = te.REPORT_NO and te.ENTRUST_STATUS IN ('2', '5', '8')
			LEFT JOIN T_INTEGRATED_ENTRUSTHISTORY tieh ON std.APPLY_TRADE_ID = tieh.REPORT_NO and tieh.ENTRUST_STATUS IN ('2', '5', '8')
			LEFT JOIN T_INTEGRATED_ENTRUST tie ON std.APPLY_TRADE_ID = tie.REPORT_NO and tie.ENTRUST_STATUS IN ('2', '5', '8')
			LEFT JOIN ETR_ENTRUST ee ON (ee.ENTRUST_ID = NVL(te.INSTRUCTION_ID, teh.INSTRUCTION_ID) OR ee.ENTRUST_ID = NVL(tie.INSTRUCTION_ID, tieh.INSTRUCTION_ID))
			LEFT JOIN PTL_PORTFOLIO ptl ON (ptl.PORTFOLIO_ID = std.PORTFOLIO_ID)

			(te.REPORT_NO IS NOT NULL OR teh.REPORT_NO IS NOT NULL OR tie.REPORT_NO IS NOT NULL OR tieh.REPORT_NO IS NOT NULL)

				AND std.DEAL_DATE = #{dealDate,jdbcType=DATE}



           			#{finprodId,jdbcType=VARCHAR}



				AND std.BUSI_TYPE = #{busiType,jdbcType=VARCHAR}



           			#{busiType,jdbcType=VARCHAR}




           			#{portfolioId,jdbcType=VARCHAR}




					#{ps,jdbcType=VARCHAR}

SELECT DISTINCT TRADE_ID_TG FROM SETTLE_TRANS_DATA t1 INNER JOIN SETTLE_TRANS_TG_MAPPING t2 ON t1.TRADE_ID = t2.TRADE_ID
t1.APPLY_TRADE_ID = #{tradeId,jdbcType=VARCHAR}
and t1.PS = #{ps,jdbcType=VARCHAR}

SELECT
NVL(te.INSTRUCTION_ID, teh.INSTRUCTION_ID) ORDER_ID,
ee.INV_AIM invAim,
stda.REPO_TYPE,

INNER JOIN SETTLE_TRANS_DATA_ADD stda ON stda.TRADE_ID=std.TRADE_ID
LEFT JOIN T_ENTRUSTHISTORY teh ON std.APPLY_TRADE_ID = teh.ENTRUST_ID
LEFT JOIN T_ENTRUST te ON std.APPLY_TRADE_ID = te.ID
LEFT JOIN ETR_ENTRUST ee ON ee.ENTRUST_ID = NVL(te.INSTRUCTION_ID, teh.INSTRUCTION_ID)

	(te.ID IS NOT NULL OR teh.ENTRUST_ID IS NOT NULL)

		AND std.DEAL_DATE = #{dealDate,jdbcType=DATE}


		AND std.BUSI_TYPE = #{busiType,jdbcType=VARCHAR}



			#{portfolioId,jdbcType=VARCHAR}




			#{ps,jdbcType=VARCHAR}



		AND stda.REPO_TYPE = #{repoType,jdbcType=VARCHAR}

SELECT DISTINCT
stda.REPO_TYPE,
sttm.TRADE_ID_TG,

INNER JOIN SETTLE_TRANS_DATA_ADD stda ON stda.TRADE_ID=std.TRADE_ID
INNER JOIN SETTLE_TRANS_TG_MAPPING sttm ON sttm.TRADE_ID=std.TRADE_ID


		AND std.DEAL_DATE = #{dealDate,jdbcType=DATE}


		AND std.BUSI_TYPE = #{busiType,jdbcType=VARCHAR}



			#{portfolioId,jdbcType=VARCHAR}




			#{ps,jdbcType=VARCHAR}



		AND stda.REPO_TYPE = #{repoType,jdbcType=VARCHAR}

SELECT PSP.PORTFOLIO_ID as portfolioId,/* 组合持仓.组合代码*/ PSP.FINPROD_ID as finprodId, /* 组合持仓.金融产品代码*/ FP.FINPROD_TYPE2 as finprodType2, /* 标的类金融产品.金融产品类型（投管）*/ FP.CCY as ccy, /*标的类金融产品.币种 */ FP.TRADE_MARKET as tradeMarket, /*标的类金融产品.币种*/ PSP.AMOUNT as redDateAmt, /*组合持仓.数量 */ MFBN.REG_DATE as regDate, /*基金分红公告.权益登记日*/ MFBN.DEL_DATE as delDate, /*基金分红公告.除权日*/ MFBN.DEVIDENT_DATE as devidentDate, /*基金分红公告.派息日*/ MFBN.UNIT_BONUS_UNIT_VALUE as unitBonusUnitValue, /*基金分红公告.单位分红净值*/ (MFBN.UNIT_BONUS_UNIT_VALUE * PSP.AMOUNT) as bonusAmt, /*基金分红公告.单位分红净值*组合持仓.数量*/ '02' as bonusMode, /*现金流支付规则表.支付方式 */ PSP.SEC_ACCT_ID as secAcctId /*组合持仓.证券账户代码*/ FROM PTL_SEC_POSITION PSP /*组合持仓*/ JOIN FIN_PRODUCT FP /*标的类金融产品*/ ON FP.FINPROD_ID = PSP.FINPROD_ID AND FP.FINPROD_TYPE2 = 'F06' AND FP.PROFIT_TYPE != '03' JOIN MST_FUND_BONUS_NOTICE MFBN /*基金分红公告*/ ON MFBN.FUND_ID = FP.FINPROD_MARKET_ID AND MFBN.REG_DATE = PSP.CDATE JOIN FIN_CASH_INFO FCI /*现金流信息*/ ON FCI.FINPROD_ID = FP.FINPROD_ID AND FCI.CASH_TYPE_2 = 'C02'
AND MFBN.DEL_DATE = #{dealDate,jdbcType=DATE}
#{portfolioId,jdbcType=VARCHAR}

SELECT A.PORTFOLIO_ID as portfolioId, A.FINPROD_ID as finprodId, C.FINPROD_TYPE2 as finprodType2, C.CCY as ccy, A.AMOUNT as redDateAmt, B.REG_DATE as regDate, B.DEL_DATE as delDate, B.DEVIDENT_DATE as devidentDate, B.REDSHARE_LISTING_DATE as redShareListingDate, B.PER_DEVIDENT_AMT as preDevidengAmt, B.PER_DEVIDENT_CASH as preDevidengCash, B.PER_DEVIDENT_CASH * A.AMOUNT as bonusAmt, B.PER_DEVIDENT_AMT * A.AMOUNT as bonusQty, A.SEC_ACCT_ID as secAcctId, C.TRADE_MARKET as tradeMarket FROM PTL_SEC_POSITION A, MST_SHARE_BONUS_NOTICE B, FIN_PRODUCT C
A.FINPROD_ID = C.FINPROD_ID AND C.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR} AND C.FINPROD_MARKET_ID = B.SHARES_ID AND A.CDATE = B.REG_DATE
#{portfolioId,jdbcType=VARCHAR}
AND B.DEL_DATE >= #{startDate,jdbcType=DATE}
AND B.DEL_DATE <= #{endDate,jdbcType=DATE}

SELECT
	A.TOTLE_TRADE_ID
FROM
	TRD_FIN_PRODUCT_DEAL_TOTAL A,
	PA_TRD_FIN_PRODUCT_DEAL_TOTAL B

	A.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} AND A.PS = #{ps,jdbcType=VARCHAR} AND A.TRADE_DATE <= #{fhDate,jdbcType=DATE} 
	AND A.TRADE_STATUS = #{tradeStatus,jdbcType=VARCHAR} AND A.IS_CANCEL = #{isCancel,jdbcType=VARCHAR} 
	AND A.TOTLE_TRADE_ID = B.TOTLE_TRADE_ID AND B.BONUS_CFM_DATE = #{fhDate,jdbcType=DATE}
